      [`${prefix}--label--disabled`]: disabled,
    });
    const helperId = !helperText
      ? undefined
      : `multiselect-helper-text-${this.multiSelectInstanceId}`;
    const labelId = `multiselect-label-${this.multiSelectInstanceId}`;
    const fieldLabelId = `multiselect-field-label-${this.multiSelectInstanceId}`;
    const title = titleText ? (
      <span id={labelId} className={titleClasses}>
        {titleText}
      </span>
    ) : null;
    const helperClasses = cx(`${prefix}--form__helper-text`, {
      [`${prefix}--form__helper-text--disabled`]: disabled,
    });
    const helper = helperText ? (
      <div id={helperId} className={helperClasses}>
        {helperText}
      </div>
    ) : null;

    const input = (
      <Selection
        disabled={disabled}
        onChange={this.handleOnChange}
        initialSelectedItems={initialSelectedItems}
        render={({ selectedItems, onItemChange, clearSelection }) => (
          <Downshift
            {...downshiftProps}
            highlightedIndex={highlightedIndex}
            isOpen={isOpen}
            itemToString={itemToString}
            onChange={onItemChange}
            onStateChange={this.handleOnStateChange}
            onOuterClick={this.handleOnOuterClick}
            selectedItem={selectedItems}
            render={({
              getRootProps,
              selectedItem,
              isOpen,
              itemToString,
              highlightedIndex,
              getItemProps,
              getButtonProps,
            }) => {
              const className = cx(
                `${prefix}--multi-select`,
                containerClassName,
                {
                  [`${prefix}--multi-select--invalid`]: invalid,
                  [`${prefix}--multi-select--inline`]: inline,
                  [`${prefix}--multi-select--selected`]:
                    selectedItem.length > 0,
                }
              );
              const buttonProps = {
                ...getButtonProps({ disabled }),
                'aria-label': undefined,
              };
              return (
                <ListBox
                  id={id}
                  aria-label={ariaLabel}
                  type={type}
                  size={size}
                  className={className}
                  disabled={disabled}
                  light={light}
                  invalid={invalid}
                  invalidText={invalidText}
                  isOpen={isOpen}
                  aria-labelledby={labelId}
                  aria-describedby={helperId}
                  {...getRootProps({ refKey: 'innerRef' })}>
                  {invalid && (
                    <WarningFilled16
                      className={`${prefix}--list-box__invalid-icon`}
                    />
                  )}
                  <ListBox.Field
                    id={id}
                    tabIndex="0"
                    disabled={disabled}
                    aria-disabled={disabled}
                    aria-labelledby={`${labelId} ${fieldLabelId}`}
                    aria-describedby={helperId}
                    {...buttonProps}>
                    {selectedItem.length > 0 && (
                      <ListBox.Selection
                        clearSelection={!disabled ? clearSelection : noop}
                        selectionCount={selectedItem.length}
                        translateWithId={translateWithId}
                        disabled={disabled}
                      />
                    )}
                    <span
                      id={fieldLabelId}
                      className={`${prefix}--list-box__label`}>
                      {label}
                    </span>
                    <ListBox.MenuIcon
                      isOpen={isOpen}
                      translateWithId={translateWithId}
                    />
                  </ListBox.Field>
                  {isOpen && (
                    <ListBox.Menu aria-label={ariaLabel} id={id}>
                      {sortItems(items, {
                        selectedItems: {
                          top: selectedItems,
                          fixed: [],
                          'top-after-reopen': this.state.topItems,
                        }[this.props.selectionFeedback],
                        itemToString,
                        compareItems,
                        locale: 'en',
                      }).map((item, index) => {
                        const itemProps = getItemProps({ item });
                        const itemText = itemToString(item);
                        const isChecked =
                          selectedItem.filter(selected =>
                            isEqual(selected, item)
                          ).length > 0;
                        return (
                          <ListBox.MenuItem
                            key={itemProps.id}
                            isActive={isChecked}
                            isHighlighted={highlightedIndex === index}
                            {...itemProps}>
                            <Checkbox
                              id={`${itemProps.id}__checkbox`}
                              title={useTitleInItem ? itemText : null}
                              name={itemText}
                              checked={isChecked}
                              disabled={disabled}
                              readOnly={true}
                              tabIndex="-1"
                              labelText={itemText}
                            />
                          </ListBox.MenuItem>
                        );
                      })}
                    </ListBox.Menu>
                  )}
                </ListBox>
              );
            }}
          />
        )}
      />
    );

    return (
      <div className={wrapperClasses}>
        {title}
        {!inline && helper}
        {input}
      </div>
    );
  }
}

